// Serves /hub-preview. GET only.
// If the request carries a valid signed session cookie, returns the real
// JATI Hub Board promo deck (embedded below as base64 so it never exists as
// a plain static file anyone could fetch directly). Otherwise returns the
// PIN gate page, which contains zero trace of the deck's markup or script.
//
// This file is never sent to the browser as source - only whichever HTML
// body it returns is. Files under /api are compiled into serverless
// functions by Vercel and are not part of the static file output.
const crypto = require('crypto');

const COOKIE_NAME = 'hubprev_session';
// HMAC signing secret for the session cookie only - NOT the PIN. Rotating
// this invalidates all existing sessions. Hardcoded per Chris's call (no env
// var needed for a single shared PIN gate); move to a Vercel env var later
// if this ever needs to rotate without a redeploy.
const SECRET = 'jati-hubpreview-3f7a9c2e5b8d1f04a6c3e9b7d2f5a8c1-signing-key';

function makeToken() {
  return crypto.createHmac('sha256', SECRET).update('hubpreview-session-v1').digest('hex');
}

function isValidToken(token) {
  if (!token) return false;
  const expected = makeToken();
  const a = Buffer.from(String(token));
  const b = Buffer.from(expected);
  if (a.length !== b.length) return false;
  return crypto.timingSafeEqual(a, b);
}

function parseCookies(header) {
  const out = {};
  if (!header) return out;
  header.split(';').forEach((part) => {
    const idx = part.indexOf('=');
    if (idx === -1) return;
    const k = part.slice(0, idx).trim();
    const v = part.slice(idx + 1).trim();
    out[k] = decodeURIComponent(v);
  });
  return out;
}

const DECK_HTML_B64 = "";

const GATE_HTML = "<!doctype html>\n<html lang=\"en\"><head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<meta name=\"robots\" content=\"noindex, nofollow\">\n<title>JATI Hub</title>\n<style>\n:root{--b:#2e419a;--d:#1e2d6e;--i:#1a1a2a}\n*{box-sizing:border-box}\nbody{margin:0;min-height:100vh;display:grid;place-items:center;background:var(--d);color:#fff;font-family:Lato,\"Segoe UI\",Arial,sans-serif}\nform{background:#ffffff10;border:1px solid #ffffff33;border-radius:12px;padding:2.5rem 2rem;width:min(320px,90vw);text-align:center}\nh1{font-size:1.05rem;font-weight:700;letter-spacing:.04em;margin:0 0 1.5rem}\ninput{width:100%;font-size:1.4rem;letter-spacing:.3em;text-align:center;padding:.7rem;border-radius:8px;border:1px solid #ffffff44;background:#ffffff10;color:#fff;margin-bottom:1rem}\ninput::placeholder{color:#ffffff66;letter-spacing:.1em;font-size:.9rem}\nbutton{width:100%;padding:.7rem;border:0;border-radius:8px;background:#3a50bc;color:#fff;font-weight:700;letter-spacing:.05em;cursor:pointer;text-transform:uppercase;font-size:.8rem}\nbutton:hover{background:#2e419a}\nbutton:disabled{opacity:.6;cursor:default}\n#err{min-height:1.2rem;color:#ffb4b4;font-size:.8rem;margin-top:.9rem}\n</style>\n</head><body>\n<form id=\"f\" autocomplete=\"off\">\n  <h1>JATI Hub</h1>\n  <input id=\"pin\" name=\"pin\" type=\"password\" inputmode=\"numeric\" pattern=\"[0-9]*\" maxlength=\"12\" placeholder=\"PIN\" autofocus>\n  <button id=\"submitBtn\" type=\"submit\">Enter</button>\n  <div id=\"err\"></div>\n</form>\n<script>\ndocument.getElementById('f').addEventListener('submit', async function (e) {\n  e.preventDefault();\n  var err = document.getElementById('err');\n  var btn = document.getElementById('submitBtn');\n  err.textContent = '';\n  btn.disabled = true;\n  var pin = document.getElementById('pin').value;\n  try {\n    var r = await fetch('/api/hub-preview-auth', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ pin: pin })\n    });\n    if (r.ok) {\n      location.reload();\n    } else {\n      err.textContent = 'Incorrect PIN.';\n      btn.disabled = false;\n    }\n  } catch (e2) {\n    err.textContent = 'Something went wrong. Try again.';\n    btn.disabled = false;\n  }\n});\n</script>\n</body></html>";

module.exports = (req, res) => {
  if (req.method !== 'GET' && req.method !== 'HEAD') {
    res.status(405).send('Method Not Allowed');
    return;
  }
  const cookies = parseCookies(req.headers.cookie);
  const authed = isValidToken(cookies[COOKIE_NAME]);

  res.setHeader('Content-Type', 'text/html; charset=utf-8');
  res.setHeader('Cache-Control', 'no-store, no-cache, must-revalidate');
  res.setHeader('X-Robots-Tag', 'noindex, nofollow');

  if (authed) {
    const deckHtml = Buffer.from(DECK_HTML_B64, 'base64').toString('utf8');
    res.status(200).send(deckHtml);
    return;
  }

  res.status(200).send(GATE_HTML);
};
